function k(o){const i=[...o].sort((n,r)=>n.x-r.x||r.y-n.y),t=[];let c=-1/0;for(const n of i)n.y>c&&(t.push(n),c=n.y);return t}function u(o,i){const[t,c]=o.acc<=i.acc?[o,i]:[i,o],n=c.acc-t.acc,r=c.inr_1k-t.inr_1k,e=(c.wh_q-t.wh_q)*1e3;return{lo:t,hi:c,dAcc:n,dInr:r,dWh:e,dCo2:c.co2_g_1k-t.co2_g_1k,inrPerPt:n>0?r/n:1/0,whPerPt:n>0?e/n:1/0,significant:c.acc_ci[0]>t.acc_ci[1]}}function l(o,i,t,c,n){let r=0,e=0,a=0,h=0;for(const f of o){const s=f.conf>=i;r+=+s,e+=+(s?f.small_ok:f.big_ok),a+=(t.inr_1k*n+(s?0:c.inr_1k))/1e3,h+=t.wh_q*n+(s?0:c.wh_q)}const _=o.length||1;return{n:o.length,pctSmall:100*r/_,acc:100*e/_,inrSaved1k:c.inr_1k-a/_*1e3,whSaved1k:(c.wh_q-h/_)*1e3}}export{u as c,k as p,l as r};
